# State [T(n), T(n-1), T(n-2)] -> [T(n+1), T(n), T(n-1)]
# T(n+1) = T(n) + T(n-2)
C = [
    [1, 1, 0],  # T(n) -> T(n+1), T(n)
    [0, 0, 1],  # T(n-1) -> T(n-1)
    [1, 0, 0],  # T(n-2) -> T(n+1)
]

def mat_mul(A, B):
    n = len(A)
    m = len(B[0])
    p = len(B)
    res = [[0]*m for _ in range(n)]
    for i in range(n):
        for k in range(p):
            if A[i][k]:
                aik = A[i][k]
                for j in range(m):
                    res[i][j] = (res[i][j] + aik * B[k][j]) % MOD
    return res

def mat_pow(M, e):
    n = len(M)
    R = [[1 if i==j else 0 for j in range(n)] for i in range(n)]
    while e:
        if e & 1:
            R = mat_mul(R, M)
        M = mat_mul(M, M)
        e >>= 1
    return R

# Test: start with [T(4), T(3), T(2)] = [9, 6, 4]
v = [9, 6, 4]
# Apply C once
v2 = [0,0,0]
for i in range(3):
    for j in range(3):
        v2[j] = (v2[j] + v[i] * C[i][j]) % MOD
print(f"After 1 step: {v2}, expected [13, 9, 6]")

# Apply C twice
Cp = mat_pow(C, 2)
v3 = [0,0,0]
for i in range(3):
    for j in range(3):
        v3[j] = (v3[j] + v[i] * Cp[i][j]) % MOD
print(f"After 2 steps: {v3}, expected [19, 13, 9]")

def T_rec(N):
    if N == 0:
        return 1
    if N == 1:
        return 2
    if N == 2:
        return 4
    if N == 3:
        return 6
    if N == 4:
        return 9
    v = [9, 6, 4]
    Cp = mat_pow(C, N-4)
    res = [0,0,0]
    for i in range(3):
        for j in range(3):
            res[j] = (res[j] + v[i] * Cp[i][j]) % MOD
    return res[0]

for n in range(1, 21):
    print(f"T_rec({n}) = {T_rec(n)}")
